// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AgreementListAgreements The tenant's DPA/DSA agreements, newest first (DPA-02)
	// (GET /admin/v1/agreements)
	AgreementListAgreements(ctx context.Context, request AgreementListAgreementsRequestObject) (AgreementListAgreementsResponseObject, error)
	// AgreementCreateAgreement DPA-02: compose a complete draft agreement from a vendor and its RoPA activities in one call — "โหมดกรอกเอง" is simply leaving template_id unset
	// (POST /admin/v1/agreements)
	AgreementCreateAgreement(ctx context.Context, request AgreementCreateAgreementRequestObject) (AgreementCreateAgreementResponseObject, error)
	// AgreementGetAgreement One agreement with its linked activity ids (DPA-02)
	// (GET /admin/v1/agreements/{id})
	AgreementGetAgreement(ctx context.Context, request AgreementGetAgreementRequestObject) (AgreementGetAgreementResponseObject, error)
	// AgreementListClauses DPA-03: every clause attached to an agreement, in position order
	// (GET /admin/v1/agreements/{id}/clauses)
	AgreementListClauses(ctx context.Context, request AgreementListClausesRequestObject) (AgreementListClausesResponseObject, error)
	// AgreementAddClause DPA-03: attach a published clause from the library to this agreement (only while it is still a draft)
	// (POST /admin/v1/agreements/{id}/clauses)
	AgreementAddClause(ctx context.Context, request AgreementAddClauseRequestObject) (AgreementAddClauseResponseObject, error)
	// AgreementRemoveClause DPA-03: detach a clause from this agreement (only while it is still a draft)
	// (DELETE /admin/v1/agreements/{id}/clauses/{clauseRowId})
	AgreementRemoveClause(ctx context.Context, request AgreementRemoveClauseRequestObject) (AgreementRemoveClauseResponseObject, error)
	// AgreementMissingClauses DPA-03: ม.40 mandatory clauses not yet attached to this agreement, computed live (the submit-for-approval gate's own read side)
	// (GET /admin/v1/agreements/{id}/missing-clauses)
	AgreementMissingClauses(ctx context.Context, request AgreementMissingClausesRequestObject) (AgreementMissingClausesResponseObject, error)
	// AgreementProcessingSchedule DPA-04: the ม.40 processing-schedule annex, composed live from every RoPA activity this agreement covers
	// (GET /admin/v1/agreements/{id}/processing-schedule)
	AgreementProcessingSchedule(ctx context.Context, request AgreementProcessingScheduleRequestObject) (AgreementProcessingScheduleResponseObject, error)
	// AgreementSetSchedule DPA-10: set the registry's own start/end dates and renewal settings — reschedules the expiry reminder
	// (PATCH /admin/v1/agreements/{id}/schedule)
	AgreementSetSchedule(ctx context.Context, request AgreementSetScheduleRequestObject) (AgreementSetScheduleResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

